package com.nm.fragmentsclean.adminImportContext.adapters.secondary.gateways.editorial; import com.nm.fragmentsclean.adminImportContext.businessLogic.ports.TopicCandidateStudioCatalog; import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.gateways.TopicCandidateRepository; import java.util.*;
public final class TopicCandidateStudioCatalogAdapter implements TopicCandidateStudioCatalog {private final TopicCandidateRepository candidates;public TopicCandidateStudioCatalogAdapter(TopicCandidateRepository candidates){this.candidates=candidates;}public List<Item> list(){return candidates.list().stream().map(c->{var s=c.snapshot();return new Item(s.id(),s.subject(),s.suggestedAngle(),s.signalIds(),s.status().name());}).toList();}}
